      var start = 0;
      var end = this.points.length - 2;
      var loopFlag = true;

      do
      {
        i = Math.floor( ( start + end ) / 2 );

        if ( this.segmentsPosition[ i ] > length )
        {
          end = i;
        }
        else if ( this.segmentsPosition[ i + 1 ] < length )
        {
          if ( i === end - 1 )
          {
            i ++;
            loopFlag = false;
          }
          else
          {
            start = i;
          }
        }
        else
        {
          loopFlag = false;
        }

