	function renderShape(graphics, base64Codes)
	{
	    function createByteArray()
	    {
	        var byteArray = $G._get('byteArray');
	        if (!byteArray)
	        {
	            if (!Bitmap)
	            {
	                trace('Bitmap库没有被加载!');
	                0();
	            }

	            var bitmapData = Bitmap.createBitmapData(1, 1);
	            byteArray = bitmapData.getPixels(bitmapData.rect);
	            byteArray.position = 0;
	            byteArray.length = 0;
	            $G._set('byteArray', byteArray);
	        }
	        return clone(byteArray);
	    }

	    function base64Decode(str)
	    {
	        var bytes = createByteArray();
	        var lookup = $G._('base64DecodeLookupTable');
	        if (!lookup)
	        {
	            lookup = [];
	            for (var n = 0; n < 256; n++)
	                lookup[n] = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'.indexOf(String.fromCharCode(n));
	            $G._set('base64DecodeLookupTable', lookup);
	        }
	        str = (str.split('\n')).join('');
	        str = (str.split('\r')).join('');
	        var c1, c2, c3, c4;
	        var i = 0, out = 0;
	        var len = str.length;

	        bytes.writeUTFBytes(str);
	        while (i < len)
	        {
	            c1 = lookup[bytes[i++] ^ 0];
	            c2 = lookup[bytes[i++] ^ 0];
	            bytes[out++] = (c1 << 2) | ((c2 & 0x30) >> 4);
	            c3 = lookup[bytes[i++] ^ 0];
	            if (c3 == -1) break;//was '='
	            bytes[out++] = ((c2 & 0x0f) << 4) | ((c3 & 0x3c) >> 2);
	            c4 = lookup[bytes[i++] ^ 0];
	            if (c4 == -1) break;//was '='
